A diffeology $\mathcal{D}$ on $X$ is a collection of parametrizations of $X$ satisfying the following axioms:

\begin{enumerate}
\item[(D1)] $\mathcal{D}$ contains the constant parametrizations.
\item[(D2)] If $p: U \rightarrow X$ is a parametrization such that $\forall u \in U$, there exists a neighborhood $V$ of $u$ such that $p|_{V}$ is in $\mathcal{D}$, then $p$ itself is in $\mathcal{D}$. In other words, the collection $\mathcal{D}$ satisfies the axioms of a set-valued sheaf.
\item[(D3)] Given a parametrization $p:U \rightarrow X$ in $\mathcal{D}$, if $f: V \rightarrow U$ is a smooth map, then $p \circ f$ is a parametrization in $\mathcal{D}$.
\end{enumerate}

A diffeological group $G$ is called a \emph{diffeological Lie group} when $T_{e}G$ is a diffeological vector space such that 
\begin{enumerate}
\item [(DL1)] For any nonzero vector $\alpha \in T_{e}G$, there exists a smooth real-valued map $T:T_{e}G \rightarrow \mathbb{R}$ such that $T(\alpha) \ne 0$:
\item [(DL2)] Every plot of $T_{e}G$ factors smoothly through a smooth linear map of a compact Hausdorff topological vector space into $T_{e}G$.
\end{enumerate}

Let $V$ and $W$ be topological graded modules over $\Gamma_{0}$. A continuous map $f : V \times \cdots \times V \rightarrow W$ is said to be an $n$-multimorphism if 
\begin{enumerate}
\item[(M1)] $f$ is $n$-multilinear with respect to the ground field $\mathbb{R}$,
\item[(M2)] $f(v_{1}, \dots v_{i}\gamma,v_{i+1}, \dots v_{n}) = f(v_{1}, \dots, v_{i}, \gamma v_{i+1}, \dots, v_{n})$, where $v_{i} \in V, 1\le i \le n$ and $\gamma \in \Gamma_{0}$,
\item[(M3)] $f(v_{1}\dots v_{n}\gamma) = f(v_{1},\dots, v_{n})\gamma$, $v_{i}\in V$, $1 \le i \le n$, $\gamma \in \Gamma_{0}$.
\end{enumerate}

(\cite{Twu} Definition 5.1.1)
 A \emph{Diffeological Category} $\mathcal{D}$ is a locally small category such that for any objects $x,y$ in $\mathcal{D}$, the hom set $\mathcal{D}(x,y)$ is a 
 diffeological space which satisfies the following axiom: for all objects $x,y$ and $z$ in $\mathcal{D}$ and elements $g$ in $\mathcal{D}(x,y)$ and $f$ in $\mathcal{D}(y,z)$, the composition $f\circ g$ in $\mathcal{D}(x,z)$ defines a smooth map:
 \begin{equation}\label{diffcat}
 \begin{aligned}
 \mathcal{D}(y,z) \times \mathcal{D}(x,y) &\rightarrow \mathcal{D}(x,z)\\
 f \times g &\mapsto f \circ g \\
 \end{aligned}
 \end{equation}
 where $\mathcal{D}(y,z) \times \mathcal{D}(x,y)$ has the product diffeology.

\label{indexformulas}
Let $F:\mathcal{J} \rightarrow \mathfrak{D}$ and $G:\mathcal{J} \rightarrow \mathcal{C}$ be smooth functors of diffeological categories. Fix an object $c$ of $\mathcal{C}$. \emph{An $(F,c)$-cylinder over $G$} is a smooth natural transformation $\alpha: F \dot{\rightarrow}\mathcal{C}(c,G-)$. It can be illustrated with the commutative diagram:
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Fi \ar[r]^{\alpha_{i}}\ar[d]_{f}& \mathcal{C}(c,Gi)\ar[d]^{\mathcal{C}(c,Gf)}\\
Fj\ar[r]_{\alpha_{j}}&\mathcal{C}(c,Gj)} 
\end{displaymath}

Let $F:\mathcal{J}^{op} \rightarrow \mathfrak{D}$ and $G: \mathcal{J} \rightarrow \mathcal{C}$ be smooth functors of diffeological categories. \emph{An $(F,c)$-cylinder under G} is a natural transformation of smooth functors $\alpha: F \dot{\rightarrow} \mathcal{C}(G-,c)$. Again, in the case $F=\Delta 1$, $\alpha: \Delta1 \dot{\rightarrow} \mathcal{C}(G-,c)$ can be identified with a cone from the base $G$ to $c$. The \emph{colimit of $G$ indexed by $F$} is the unique (up to isomorphism) object of $\mathcal{C}$ such that every $(F,c)$- cylinder under $G$ factors uniquely through the universal cylinder $\mu: F\dot{\rightarrow} \mathcal{C}(G-,F*G)$. The commutative diagram illustrating the definition is given below.

\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Fi \ar[r]^{\alpha_{i}}\ar@{}[d]_{=}& \mathcal{C}(Gi,c)\\
Fi\ar[r]^{\mu_{i}} &\mathcal{C}(Gi,F*G)\ar@{-->}[u]_{\mathcal{C}(1,t)}} 
\end{displaymath}

where $t: F\ast G \rightarrow c$ is the unique map. Hence $\alpha_{i} = \mathcal{C}(1,t)\mu_{i}$.

Let $F: \mathcal{J} \rightarrow \mathfrak{D}$ and $G: \mathcal{J} \rightarrow \mathcal{C}$ be smooth functors, where $\mathcal{C}$ is a diffeological category. For any object $c$ of $\mathcal{C}$, we have the following isomorphism of diffeological spaces:
\begin{equation}
\mathcal{C}(c, \{F,G\}) \simeq \{F,\mathcal{C}(c, G-)\}.
\end{equation}

$\mathcal{C}(c,G-)$ is a smooth functor from $\mathcal{J}$ to $\mathfrak{D}$, so applying the previous proposition (\ref{natend}) and the definition of indexed limit \eqref{eq:limit}, we have
\begin{displaymath}
\begin{aligned}
\mathcal{C}(c, \{F,G\}) &\simeq \mathfrak{D}^{\mathcal{J}}(F, \mathcal{C}(c,G-))\\
&= Nat(F,\mathcal{C}(c,G-))\\
&\simeq \{F,C(c,G-)\}\\
\end{aligned}
\end{displaymath}

Let $F \mathcal{J}^{op} \rightarrow \mathfrak{D}$  and $G: \mathcal{J} \rightarrow \mathcal{C}$ be smooth functors, where $\mathcal{C}$ is a diffeological category. For any object $c$ of $\mathcal{C}$, we have the following isomorphism of diffeological spaces:
\begin{equation}
\mathcal{C}(F\ast G, c) \simeq \{F,\mathcal{C}(G-, c)\}.
\end{equation}

$\mathcal{C}(G-,c):\mathcal{J}^{op} \rightarrow \mathfrak{D}$ is a smooth functor, so applying the definition of indexed colimits and Proposition \ref{natend} we get
\begin{displaymath}
\mathcal{C}(F*G,c) \simeq \mathfrak{D}^{\mathcal{J}^{op}}(F, \mathcal{C}(G-,c)) = Nat(F, \mathcal{C}(G-,c)) \simeq \{F,\mathcal{C}(G-,c)\}
\end{displaymath}

The limiting cone for the composite functor $elF\xrightarrow{Q}\mathcal{C} \xrightarrow{G} \mathfrak{D}$ consists of objects $\alpha_{(c,x)}: \star \rightarrow Gc$, where $\star$ denotes a 1-point set. For a map $f^{*}: (c,x) \rightarrow (c^{\prime},x^{\prime})$, $Gf \alpha_{(c,x)} = \alpha_{(c^{\prime},x^{\prime})}$, since $\alpha$ is a cone. Define a natural transformation $\beta: F\dot{\rightarrow}G $ by $\beta_{c}(x) := \alpha_{(c,x)}$. For $f^{*}: (c,x) \rightarrow (c^{\prime},x^{\prime})$, we have:
\begin{displaymath}
\begin{aligned}
Gf(\beta_{c}(x)) &= Gf\alpha_{(c,x)}= \alpha_{(c^{\prime},x^{\prime})}\\
\beta_{c^{\prime}}(Ff(x)) &= \beta_{c^{\prime}}(x^{\prime}) = \alpha_{(c^{\prime},x^{\prime})}
\end{aligned}
\end{displaymath} giving the following
commutative diagram:
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{
Fc\ar[r]^{\beta_{c}}\ar[d]_{Ff} & Gc\ar[d]^{Gf}\\
Fc^{\prime}\ar[r]_{\beta_{c^{\prime}}} & Gc^{\prime}
}
\end{displaymath}
Hence $Nat(F,G) \simeq \text{Lim\text{ }}(elF\xrightarrow{Q}\mathcal{C} \xrightarrow{G} \mathfrak{D}) \simeq \{F,G\}$.

\label{replim1}
Let $G: \mathcal{C} \rightarrow \mathcal{B}$ be a smooth functor of diffeological categories. Then given a smooth index functor $F: \mathcal{C} \rightarrow  \mathfrak{D}$,
\begin{displaymath}
\{F,G\} \simeq \text{Lim\text{ }}(elF \xrightarrow{Q} \mathcal{C} \xrightarrow{G} \mathcal{B})
\end{displaymath}

Equation \eqref{repcolim} gives $F \simeq \text{Colim\text{ }} \left(elF \xrightarrow{Q} \mathcal{C} \xrightarrow{y^{-1}} \mathfrak{D}^{\mathcal{C}}\right) \simeq \text{Colim\text{ }} \left(C(c,-): el F \rightarrow \mathfrak{D}^{\mathcal{C}}\right)$. Therefore:
\begin{displaymath}
\begin{aligned}
\{F,G\} \simeq \{\text{Colim\text{ }} \mathcal{C}(c,-),G\} & \simeq \{\Delta 1*\mathcal{C}(c,-),G\}\\
&\simeq \left\{\Delta 1,\{\mathcal{C}(c,-), G\}\right\}\\
&\simeq \{\Delta 1,Gc\}\\
&\simeq \text{Lim\text{ }}_{(c \in elF) } {Gc} 
\end{aligned} 
\end{displaymath}
where the canonical limit is indexed by the category $el F$ of elements of $F$.
On the other hand, $\text{Lim\text{ }}(elF \xrightarrow{Q} \mathcal{C} \xrightarrow{G} \mathcal{B}) = \text{Lim\text{ }}_{(c \in el F)}{Gc}$. This establishes the isomorphism.

\label{repcolim2}
\begin{displaymath}
F*G \simeq \text{Colim\text{ }} \left((elF)^{op} \xrightarrow{Q^{op}} \mathcal{C} \xrightarrow{G} \mathcal{B}\right)
\end{displaymath}

As before, Theorem \eqref{repcolim} gives a representation of $F$, this time as $F \simeq \text{Colim\text{ }} \mathcal{C}(-,c)$ since $F$ is a contravariant functor. Therefore 
\begin{displaymath}
\begin{aligned}
F*G &\simeq \left(\text{Colim\text{ }}\mathcal{C}(-,c)\right)*G\\
&\simeq (\Delta 1*\mathcal{C}(-,c))*G \\
&\simeq \Delta 1*\left(\mathcal{C}(-,c)*G \right)\\
&\simeq \Delta 1*(Gc)\\
&\simeq \text{Colim\text{ }}_{(c \in elF)}(Gc)\\
\end{aligned}
\end{displaymath}
The other side of the isomorphism is $\text{Colim\text{ }}\left((elF)^{op} \xrightarrow{Q^{op}} \mathcal{C} \xrightarrow{G} \mathcal{B} \right) = \text{Colim\text{ }}_{(c \in elF)}Gc$. The isomorphism is now established.

\label{rightkandef}
\begin{displaymath}
\text{Lim\text{ }} \left[(c\downarrow K)\xlongrightarrow{Q} \mathcal{M} \xlongrightarrow{T} \mathcal{A} \right] \simeq \{\mathcal{C}(c,K-),T \}
\end{displaymath}

We first construct a smooth natural transformation $\mu: RK \dot{\longrightarrow} T$. Since $Rc = \{\mathcal{C}(c,K-),T\}$ is the limit of $T$ indexed by $\mathcal{C}(c,K-)$, equation \eqref{eq:limit} from definition \eqref{indexformulas}  gives a universal arrow $\lambda_{c,-}: \mathcal{C}(c,K-) \dot{\longrightarrow} \mathcal{A}(Rc,T-)$. Suppose $c = Km$ for some object $m$ of $\mathcal{M}$. This gives the transformation
$\lambda_{Km,-}:\mathcal{C}(Km,K-) \dot{\longrightarrow} \mathcal{A}(RKm,T-)$. Choosing the second component of $\lambda$ to be $m$ gives
\begin{displaymath}
\lambda_{Km,m}: \mathcal{C}(Km,Km) \dot{\longrightarrow} \mathcal{A}(RKm,Tm)
\end{displaymath}
Now define $\varepsilon_{m}: RKm \rightarrow Tm$ as $\varepsilon_{m} = \lambda_{Km,m}(1_{Km})$, where $1_{Km}$ is the identity map in $\mathcal{C}(Km, Km)$. We need to show that $\varepsilon_{m}$ forms the component of a smooth natural transformation $\varepsilon: RK \dot{\longrightarrow} T$. Let $g: m \rightarrow n$ be an arrow in $\mathcal{M}$. We have the following commutative diagram:
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Km \ar[r]\ar[d]_{Kg} & Km\ar[d]^{Kg}\\
Kn\ar[r] & Kn}
\end{displaymath}
from which we deduce clearly that $1_{Kn}\circ Kg = Kg \circ 1_{Km}$. 

Now consider the following commutative diagrams
\begin{equation}\label{commdiag1}
\xymatrixcolsep{5pc}\xymatrixrowsep{4pc}\xymatrix{\mathcal{C}(Km,Km) \ar[r]^{\lambda_{Km,m}}\ar[d]_{\mathcal{C}(1,Kg)} & \mathcal{A}(RKm,Tm)\ar[d]^{\mathcal{A}(1,Tg)}\\
\mathcal{C}(Km,Kn) \ar[r]^{\lambda_{Km,n}} & \mathcal{A}(RKm,Tn)\\
\mathcal{C}(Kn,Kn) \ar[r]^{\lambda_{Kn,n}}\ar[u]^{\mathcal{C}(Kg,1)} & \mathcal{A}(RKn,Tn)\ar[u]_{\mathcal{A}(RKg,1)}}
\end{equation}
Both the upper and lower squares commute, since $\lambda$ is a universal arrow.
\begin{equation}\label{comdiag2}
\xymatrixcolsep{4pc}\xymatrixrowsep{4pc}\xymatrix{1_{Km}\ar@{|->}[r]\ar@{|->}[d] & \varepsilon_{m}\ar@{|->}[d] \\
Kg \circ 1_{Km}\ar@{|->}[r] & \lambda_{Km,n}(Kg \circ 1_{Km})= Tg \circ \varepsilon_{m} }
\end{equation}
\begin{equation}\label{comdiag3}
\xymatrixcolsep{4pc}\xymatrixrowsep{4pc}\xymatrix{1_{Kn} \circ Kg\ar@{|->}[r] & \lambda_{Km,n}(1_{Kn} \circ Kg)= RKg \circ \varepsilon_{n}\\
1_{Kn}\ar@{|->}[r]\ar@{|->}[u] & \varepsilon_{n}\ar@{|->}[u] }
\end{equation}
The result $1_{Kn}\circ Kg = Kg \circ 1_{Km}$ enables us to conclude from the commutative diagrams that $Tg \circ \varepsilon_{m}=
RKg \circ \varepsilon_{n}$, establishing the natural transformation $\varepsilon: RK \dot{\longrightarrow}T$.

Now suppose $S:\mathcal{C} \longrightarrow \mathcal{A}$ is a smooth functor with $\sigma: SK \dot{\longrightarrow} T$ a smooth natural transformation. We show that $\sigma$ uniquely factors through $\varepsilon$ by means of the adjunction in equation \eqref{adjunction1}. We shall use Kelly's approach by employing the calculus of ends and coends. We have:

\begin{displaymath}
\begin{aligned}
Nat(S,R) &= \mathcal{A^{C}}(S,R) \\
&\simeq \int_{c}\mathcal{A}(Sc,Rc) \\
&= \int_{c} \mathcal{A}\left(Sc,\{\mathcal{C}(c,K-),T \} \right)\\
\end{aligned}
\end{displaymath}
 Applying equation \eqref{eq:limit}  in the case where $F =\mathcal{C}(c,K-)$ and $G = T$, we have 
 \begin{displaymath}
 \begin{aligned}
 \mathcal{A}\left(Sc,\{\mathcal{C}(c,K-),T \} \right)&\simeq  \mathfrak{D}^{\mathcal{M}}\left[\mathcal{C}(c,K-),\mathcal{A}(Sc,T-) \right]\\
\therefore \quad \int_{c} \mathcal{A}\left(Sc,\{\mathcal{C}(c,K-),T \} \right)&\simeq \int_{c} \mathfrak{D}^{\mathcal{M}}\left[\mathcal{C}(c,K-),\mathcal{A}(Sc,T-) \right]\\
\text{ Now } \mathfrak{D}^{\mathcal{M}}\left[\mathcal{C}(c,K-),\mathcal{A}(Sc,T-) \right]&= Nat\left(\mathcal{C}(c,K-),\mathcal{A}(Sc,T-) \right). \\
\end{aligned}
\end{displaymath}
Writing the above equation as an end, we get
\begin{displaymath}
\begin{aligned}
\mathfrak{D}^{\mathcal{M}}\left[\mathcal{C}(c,K-),\mathcal{A}(Sc,T-) \right]&= \int_{m}\mathfrak{D}\left[\mathcal{C}(c,Km), \mathcal{A}(Sc, Tm) \right] \\
\text{So, }\int_{c}\mathcal{A}\left(Sc,\{\mathcal{C}(c,K-),T \} \right) &\simeq \int_{c}\int_{m}\mathfrak{D}\left[\mathcal{C}(c,Km), \mathcal{A}(Sc, Tm) \right] \\
\end{aligned}
\end{displaymath}
Applying the Fubini Theorem,
\begin{displaymath}
\begin{aligned}
\int_{c}\mathcal{A}\left(Sc,\{\mathcal{C}(c,K-),T \} \right) &\simeq \int_{m}\int_{c}\mathfrak{D}\left[\mathcal{C}(c,Km), \mathcal{A}(Sc, Tm)  \right]\\
&\simeq \int_{m}\mathfrak{D}^{\mathcal{C}^{op}}\left[\mathcal{C}(-,Km),\mathcal{A}(S-,Tm) \right] \\
&\simeq \int_{m} \mathcal{A}(SKm, Tm)\\
&\simeq \mathcal{A^{M}}(SK,T) = Nat(SK,T)\\
\end{aligned}
\end{displaymath} 
The isomorphism $Nat(S,R) \simeq Nat(SK,T)$ gives by Yoneda's Proposition (\cite {Mac}, Proposition $III.2.1$) that the natural transformation $\varepsilon :RK \dot{\longrightarrow} T$ is universal. Hence $(R, \varepsilon)$ is a right Kan extension of the smooth functor $T$.

\begin{displaymath}
\text{Colim\text{ }} \left[(K\downarrow c) \xlongrightarrow{Q^{op}} \mathcal{M} \xlongrightarrow{T} \mathcal{A}\right] \simeq \mathcal{C}(K-,c) * T
\end{displaymath}

From proposition \eqref{repcolim2}, we have for $F = \mathcal{C}(K-,c)$ and $G=T: \mathcal{M} \longrightarrow \mathcal{A}$ the result
\begin{displaymath}
\text{Colim\text{ }} \left[(elF)^{op} \xlongrightarrow{Q^{op}} \xlongrightarrow{T} \right] \simeq F * T
\end{displaymath}
Since $(el F) = (K \downarrow c)$, the result holds.

From definition \eqref{indexformulas}, there exits a universal arrow $\lambda_{-,c}: \mathcal{C}(K-,c) \dot{\longrightarrow} \mathcal{A}(T-,Lc)$. Suppose $c = Km$ for some object $m$ of $\mathcal{M}$. We obtain the transformation $\lambda_{-,Km}: \mathcal{C}(K-,Km) \dot{\longrightarrow} \mathcal{A}(T-,LKm)$. Choosing the first component of $\lambda$ to be $m$, we get
\begin{displaymath}
\lambda_{m,Km}: \mathcal{C}(Km,Km) \dot{\longrightarrow} \mathcal{A}(Tm,LKm)
\end{displaymath} 
Define $\varepsilon: T \dot{\longrightarrow} LK$ by $\varepsilon_{m}= \lambda_{m,Km}(1_{Km}): Tm \longrightarrow LKm$. Just like in the  proof for the case of the right Kan extension, we show that this definition gives a universal natural transformation. Let $g:m\rightarrow n$ be an arrow in $\mathcal{M}$. We have the equality $1_{Kn} \circ Kg = Kg \circ 1_{Km}$. Consider the following commutative diagrams:
\begin{equation}\label{commdiag1}
\xymatrixcolsep{5pc}\xymatrixrowsep{4pc}\xymatrix{\mathcal{C}(Km,Km) \ar[r]^{\lambda_{m,Km}}\ar[d]_{\mathcal{C}(1,Kg)} & \mathcal{A}(Tm,LKm)\ar[d]^{\mathcal{A}(1,LKg)}\\
\mathcal{C}(Km,Kn) \ar[r]^{\lambda_{m,Kn}} & \mathcal{A}(Tm,LKn)\\
\mathcal{C}(Kn,Kn) \ar[r]^{\lambda_{Kn,n}}\ar[u]^{\mathcal{C}(Kg,1)} & \mathcal{A}(Tn,LKn)\ar[u]_{\mathcal{A}(Tg,1)}}
\end{equation}
Both the upper and lower squares commute, since $\lambda$ is a universal arrow. Splitting the diagram into two components and evaluating the identity map for each component gives
\begin{equation}\label{comdiag2}
\xymatrixcolsep{4pc}\xymatrixrowsep{4pc}\xymatrix{1_{Km}\ar@{|->}[r]\ar@{|->}[d] & \varepsilon_{m}\ar@{|->}[d] \\
Kg \circ 1_{Km}\ar@{|->}[r] & \lambda_{m,Kn}(Kg \circ 1_{Km})= LKg \circ \varepsilon_{m} }
\end{equation}
\begin{equation}\label{comdiag3}
\xymatrixcolsep{4pc}\xymatrixrowsep{4pc}\xymatrix{1_{Kn} \circ Kg\ar@{|->}[r] & \lambda_{m,Kn}(1_{Kn} \circ Kg)= Tg \circ \varepsilon_{n}\\
1_{Kn}\ar@{|->}[r]\ar@{|->}[u] & \varepsilon_{n}\ar@{|->}[u] }
\end{equation}
From the result $1_{Kn}\circ Kg = Kg \circ 1_{Km}$ we get $Tg \circ \varepsilon_{n}=
LKg \circ \varepsilon_{m}$, establishing the natural transformation $\varepsilon: T \dot{\longrightarrow}LK$. This gives the diagram
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Tm\ar[r]^{\varepsilon_{m}}\ar[d]_{Tg} & LKm\ar[d]^{LKg}\\
Tn\ar[r]_{\varepsilon_{n}} & LKn \\
}
\end{displaymath}
Finally, we show that $\varepsilon: T \dot{\longrightarrow} LK$ is unique up to natural isomorphism. Let $S: \mathcal{C} \longrightarrow \mathcal{A}$ be a smooth functor with $\sigma: T \dot{\longrightarrow} SK$ a natural transformation. We have:
\begin{displaymath}
\begin{aligned}
Nat(L,S) &\simeq \mathcal{A}^{\mathcal{C}}(L,S)\\
&\simeq \int_{c}\mathcal{A}(Lc, Sc) \\
&\simeq \int_{c}\mathcal{A}(\mathcal{C}(K-,c)*T,Sc)\\
\end{aligned}
\end{displaymath}
by the definition of $Lc$. Applying equation \eqref{repcolim2}, we have
\begin{displaymath}
\begin{aligned}
\mathcal{A}(\mathcal{C}(K-,c)*T,Sc) &\simeq \mathfrak{D}^{\mathcal{M}^{op}}\left[\mathcal{C}(K-,c),\mathcal{A}(T-,Sc) \right]\\
\text{ Therefore } \int_{c}\mathcal{A}(\mathcal{C}(K-,c)*T,Sc) &\simeq \int_{c}\mathfrak{D}^{\mathcal{M}^{op}}\left[\mathcal{C}(K-,c),\mathcal{A}(T-,Sc) \right]\\
& \simeq \int_{c}\int_{m}\mathfrak{D}\left[\mathcal{C}(Km,c),\mathcal{A}(Tm, Sc) \right]\\
\end{aligned}
\end{displaymath}
Applying the Fubini theorem, we get
\begin{displaymath}
\begin{aligned}
\int_{c}\mathcal{A}(\mathcal{C}(K-,c)*T,Sc) &\simeq \int_{m}\int_{c}\mathfrak{D}\left[\mathcal{C}(Km,c),\mathcal{A}(Tm,Sc) \right]\\
&\simeq \int_{m}\mathfrak{D}^{\mathcal{C}}\left[\mathcal{C}(Km,-), \mathcal{A}(Tm, S-) \right]\\
&\simeq \mathcal{A}(Tm, SKm)\\
&\simeq \mathcal{A}^{\mathcal{M}}(T,SK) = Nat (T, SK)\\
\end{aligned}
\end{displaymath}
Hence by Yoneda's Proposition (\cite{Mac}, Proposition $III.2.1$), the isomorphism $ Nat(L,S) \simeq Nat(T, SK)$ gives the result that the natural transformation $\varepsilon: T \dot{\longrightarrow} LK$ is universal, establishing that $(L,\varepsilon)$ is a left Kan extension of $T$ along $K$.

By the definition of $R$, the orthogonal projection of  
${F\alpha (f_{j})\cdot g_{i}} - {f_{j}\cdot G\alpha( g_{i})}$ gives the zero vector in $R^{\bot}$. 








We define the universal cylinder $\lambda: F \dot{\longrightarrow} \mathcal{C}(G-, R^{\bot})$ by means of the projection $Fi \times Gi \hookrightarrow V \xlongrightarrow{\pi} R^{\bot}$ , where the projection is given by the composition
\begin{displaymath}
f_{i}\cdot g_{i} \longmapsto \sum f_{i}\cdot g_{i} \longrightarrow \pi(f_{i}\cdot g_{i})
\end{displaymath}
where the sum is taken over all $i$ in $\mathcal{J}$ and $g_{i}$ in $G_{i}$. This gives $\lambda_{i}: Fi \rightarrow \mathcal{C}(Gi, R^{\bot})$ as follows: fix an element $f_{i}$ of $Fi$. We have the map
 \begin{displaymath}
 \begin{aligned}
 \lambda_{i}(f_{i}): Gi &\longrightarrow R^{\bot}\\
 \left(\lambda_{i}(f_{i})\right)g_{i} &= \pi(f_{i}\cdot g_{i}) \\
 \end{aligned}
 \end{displaymath}
 We show that $\lambda_{i}(f_{i})$ is an arrow of $\mathcal{C}$. The norm of $\lambda_{i}(f_{i})$ is given by
 \begin{displaymath}
 ||\lambda_{i}(f_{i})|| = \sup_{\substack{g_{i}\in Gi\\ g_{i}\ne0}} \frac{||\pi(f_{i}\cdot g_{i})||}{||g_{i}||} \le \sup_{\substack{g_{i}\in Gi\\ g_{i}\ne0}} \frac{||f_{i}\cdot g_{i}||}{||g_{i}||} = 1
 \end{displaymath}
 since $\pi$ is an orthogonal projection and therefore has norm $||\pi|| \le 1$ and $||f_{i}\cdot g_{i}|| = ||g_{i}||$.




The naturality of $\lambda$ is given by the following diagram: 
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Fi\ar[r]^{\lambda_{i}} & \mathcal{C}(Gi, R^{\bot}) \\
Fj\ar[u]^{F\alpha}\ar[r]_{\lambda_{j}} & \mathcal{C}(Gj, R^{\bot})\ar[u]_{\mathcal{C}(G\alpha,R^{\bot})}}
\end{displaymath}
All the maps in the diagram are smooth maps of diffeological spaces. 

We show that the diagram commutes. Let $f_{j}$ be an element of the diffeological space $Fj$. We have:
\begin{displaymath}
\begin{aligned}
\lambda_{i}(F\alpha(f_{j}))g_{i} &= \pi(F\alpha(f_{j})\cdot g_{i})\\
	&= \pi(f_{j}\cdot G\alpha(g_{i})) \quad \text{by the definition of }R\\
	&= \lambda_{j}(f_{i})(G\alpha(g_{i})). 
\end{aligned}
\end{displaymath} 

Therefore the diagram commutes and $\lambda: F \dot{\longrightarrow} \mathcal{C}(G-,R^{\bot})$ is a cylinder. 
To show that $\lambda: F\dot{\longrightarrow} \mathcal{C}(G-, R^{\bot})$ is a universal cylinder, suppose we have another $(F,c)-$cylinder $\beta: F \dot{\longrightarrow} (G-,c)$. This gives the commutative diagram illustrated below.

\begin{equation}\label{newcylinder}
\xymatrixcolsep{5pc}\xymatrix{Fi\ar[r]^{\beta_{i}} & \mathcal{C}(Gi,c)\\
Fj\ar[u]^{F\alpha}\ar[r]_{\beta_{j}} & \mathcal{C}(Gj,c)\ar[u]_{\mathcal{C}(G\alpha,c)}}
\end{equation}
Therefore for each $f_{j}$ in $Fj$, $\beta_{i}(F\alpha (f_{j}))(g_{i})=\beta_{i}(f_{j})(G\alpha (g_{i}))$.

The unique map $T: R^{\bot} \rightarrow c$ is defined as $T\left[\pi\left(f_{i}\cdot g_{i}\right) \right] = \left(\beta_{i}(f_{i})\right)(g_{i})$. We show that $T$ is well defined by proving that the generators of $R$ under the action of $T$ give the zero vector in $c$. Pick a generator $F\alpha (f_{j})\cdot g_{i} - f_{j}\cdot G\alpha( g_{i})$ in $R$. Then $\pi(F\alpha (f_{j})\cdot g_{i} - f_{j}\cdot G\alpha( g_{i})) = \pi(F\alpha (f_{j})\cdot g_{i}) - \pi({f_{j}\cdot G\alpha( g_{i})}) = 0$ in $R^{\bot}$. We have 
\begin{displaymath}
\begin{aligned} 
T\left[\pi(F\alpha (f_{j})\cdot g_{i}) - \pi({f_{j}\cdot G\alpha( g_{i})}) \right] &= \beta_{i}(F\alpha (f_{j}))(g_{i})-\beta_{i}(f_{j})(G\alpha (g_{i}))\\
& = 0,
\end{aligned}
\end{displaymath}
by the commutative diagram \eqref{newcylinder}.
Hence for all pairs $(f_{i},g_{i})$ such that (by means of the inclusion map) $f_{i}\cdot g_{i}$ is in  $R$, $(\beta_{i}f_{i})= 0$ in $c$.

Now we compute the norm of $T$. We have the following commutative diagrams:
\begin{displaymath}
\xymatrixcolsep{5pc}\xymatrix{Fi \times Gi\ar[d]_{\pi}  \ar[r] & c\\
R^{\bot}\ar@{-->}[ru]_{T}}
\xymatrixcolsep{5pc}\xymatrix{(f_{i},g_{i})\ar@{|->}[d]  \ar@{|->}[r] & \beta_{i}(f_{i})g_{i}\\
\pi(f_{i}\cdot g_{i})\ar@{|-->}[ru]}
\end{displaymath}
We have
\begin{equation}\label{normT}
||T|| = \sup_{\substack{g_{i} \in Gi\\g_{i}\ne 0}}\frac{||\beta_{i}(f_{i})g_{i}||}{||\pi(f_{i}\cdot g_{i})||}
\end{equation}
Fix a pair $(f_{i},g_{i})$ in $Fi \times Gi$. We have that $||\pi(f_{i}\cdot g_{i})|| \le ||f_{i}\cdot g_{i}||$. If $||\pi(f_{i}\cdot g_{i})|| = ||f_{i}\cdot g_{i}||$, then we have 

\begin{displaymath}
\frac{||\beta_{i}(f_{i})g_{i}||}{||\pi(f_{i}\cdot g_{i})||}=\frac{||\beta_{i}(f_{i})g_{i}||}{||f_{i}\cdot g_{i}||}\le \frac{||g_{i}||}{||f_{i}\cdot g_{i}||} = 1.
\end{displaymath}
Now if $||\pi(f_{i}\cdot g_{i})|| < ||f_{i}\cdot g_{i}||$, then we can decompose $f_{i}\cdot g_{i}$ in $V$ into the components in $R$ and $R^{\bot}$ to get $f_{i}\cdot g_{i} = f_{i}\cdot g_{i}^{\prime} + f_{i}\cdot g_{i}^{\prime\prime}$, where $f_{i}\cdot g_{i}^{\prime}$ is in $R$ and $f_{i}\cdot g_{i}^{\prime\prime}$ is in $R^{\bot}$. We can express $f_{i}\cdot g_{i}^{\prime}$ as $f_{i}\cdot g_{i}^{\prime} = F\alpha (h_{j})\cdot g_{i}^{\prime} - h_{j} \cdot G\alpha(g_{i}^{\prime})$, where $h_{j}$ is in $F_{j}$ and $\alpha$ is an arrow in $\mathcal{J}$. Since $\beta$ is a $(F,c)-$cylinder under $G$, $\beta_{i}(f_{i})g_{i} = \beta_{i}\left[F\alpha (h_{j})\cdot g_{i}^{\prime} - h_{j} \cdot G\alpha(g_{i}^{\prime}) \right]=0$. Hence we have the following results:
\begin{displaymath}
\begin{aligned}
\text{In } R^{\bot},\quad ||\pi(f_{i}\cdot g_{i})|| &=||f_{i}\cdot g_{i}^{\prime\prime}|| = ||g_{i}^{\prime\prime}||\\
\text{In } c,\quad ||\beta_{i}(f_{i})g_{i}||&= ||\beta_{i}(f_{i})g_{i}^{\prime\prime}||\le ||g_{i}^{\prime\prime}||\\
\therefore\quad \frac{||\beta_{i}(f_{i})g_{i}||}{||\pi(f_{i}\cdot g_{i})||}&= \frac{||\beta_{i}(f_{i})g_{i}^{\prime\prime}||}{||f_{i}\cdot g_{i}^{\prime\prime}||} \le \frac{||g_{i}^{\prime\prime}||}{||g_{i}^{\prime\prime}||} = 1
\end{aligned}
\end{displaymath}
Therefore, in both cases we have   
\begin{displaymath}
||T|| = \sup_{\substack{g_{i} \in Gi\\g_{i}\ne 0}}\frac{||\beta_{i}(f_{i})g_{i}||}{||\pi(f_{i}\cdot g_{i})||} \le 1
\end{displaymath}
Hence T is an arrow in $\mathcal{C}$ and
$\lambda$, as defined is a universal cylinder.
We conclude that $R^{\bot} = F \ast G$.
